messages = [
    ('create order 9', 'normal'),
    ('cancel order 9', 'expedited'),
]
def consume(order):
    state = 'no order'
    log = []
    for name, _ in order:
        if name.startswith('create'):
            state = 'order open'
        elif name.startswith('cancel'):
            if state == 'order open':
                state = 'cancelled'
            else:
                log.append('cancel ignored: no such order')
    if state == 'order open':
        state = 'SHIPPED'
    return state, log
priority_order = sorted(messages, key=lambda m: 0 if m[1] == 'expedited' else 1)
print('priority order -> final state:', consume(priority_order))
print('send order     -> final state:', consume(messages))

