MANIFEST = {'columns': ['id', 'category', 'amount'], 'rows': 4, 'sum': 10000, 'census': {'web': 2, 'store': 2}, 'canary': 7777}
def census(rows):
    out = {}
    for r in rows:
        out[r['category']] = out.get(r['category'], 0) + 1
    return out
def guarded_load(rows, canary_landed):
    checks = {}
    checks['schema'] = all(list(r.keys()) == MANIFEST['columns'] for r in rows)
    checks['row_count'] = len(rows) == MANIFEST['rows']
    checks['sum'] = sum(r['amount'] for r in rows) == MANIFEST['sum']
    checks['census'] = census(rows) == MANIFEST['census']
    checks['canary'] = canary_landed == MANIFEST['canary']
    failed = [k for k, ok in checks.items() if not ok]
    return ('PUBLISH' if not failed else f'REJECT (failed: {", ".join(failed)})'), checks
faulty = [{'id': 1, 'category': 'web', 'amount': 4000}, {'id': 2, 'category': 'web', 'amount': 3000}, {'id': 3, 'category': 'web', 'amount': 2000}, {'id': 4, 'category': 'store', 'amount': 900}]
clean = [{'id': 1, 'category': 'web', 'amount': 4000}, {'id': 2, 'category': 'web', 'amount': 3000}, {'id': 3, 'category': 'store', 'amount': 2000}, {'id': 4, 'category': 'store', 'amount': 1000}]
print('faulty batch:', guarded_load(faulty, 7700))
print('clean batch :', guarded_load(clean, 7777))
